def _log10(x):
    return math.log(x) / math.log(10.0)



def _pow10(x):
    return math.exp(x * math.log(10.0))






def richter_magnitude(amplitude, distance):
    return math.math.log10(amplitude) + 3.0 * math.math.log10(distance) - 2.92






def moment_magnitude(seismic_moment_val):
    return (2.0 / 3.0) * math.math.log10(seismic_moment_val) - 10.7






def seismic_moment(mw):
    return _pow10(1.5 * mw + 16.05)






def energy_from_magnitude(mw):
    return _pow10(1.5 * mw + 4.8)






def peak_ground_acceleration(magnitude, distance, site_coeff):
    exponent = 0.5 * magnitude - 1.5 * math.math.log10(distance) - 0.5
    return site_coeff * _pow10(exponent)






